function memoize(fn) {
  const cache = new Map()
  let n = 0
  const m = (...args) => {
    const k = JSON.stringify(args)
    if (!cache.has(k)) { n++; cache.set(k, fn(...args)) }
    return cache.get(k)
  }
  m.calls = () => n
  return m
}
